package glitch

import data.glitch_lib

# Detect insecure protocol or URL usage in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check AtomicUnits for insecure configurations
    atomic_units := glitch_lib.all_atomic_units(parent)
    unit := atomic_units[_]

    # Get all attributes including those in nested Hash structures
    all_attrs := glitch_lib.all_attributes(unit)

    # Also check variables for insecure configurations (for Ansible vars files)
    all_vars := glitch_lib.all_variables(parent)

    # Combine attributes and variable values for checking
    check_nodes := array.concat([n | n := all_attrs[_]], [n | n := all_vars[_]])
    node := check_nodes[_]

    # Check for insecure URL/protocol patterns
    is_insecure := check_insecure_configuration(node)

    is_insecure

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "CWE-353: Insecure transmission protocol or URL detected (missing integrity checks)"
    }
}

# Helper function to check if a node contains insecure configuration
check_insecure_configuration(node) {
    # Check if node is an Attribute or Variable with insecure value
    node.ir_type in {"Attribute", "Variable"}
    node.value.ir_type == "String"
    regex.match("(?i)^(http://|ftp://|tcp://|udp://)", node.value.value)
} else {
    # Check Attribute/Variable name for insecure flags
    node.ir_type in {"Attribute", "Variable"}
    node.name in {"url", "source", "baseurl", "mirrorlist", "endpoint"}
    node.value.ir_type == "String"
    regex.match("(?i)^http://", node.value.value)
} else {
    # Check for disabled TLS/SSL
